const hour = $now.hour;

const grupos = [
  '593961230380-1588719606@g.us',
  '120363291497664389@g.us',
  '593961230380-1588719963@g.us'
];

if (hour < 12) {
  return {
    tipo: 'apertura',
    grupos: grupos,
    stickerUrl: 'https://grupojk-cambios.github.io/grupojk-conversor/logos/sticker-apertura.webp'
  };
} else {
  return {
    tipo: 'cierre',
    grupos: grupos,
    imageUrl: 'https://raw.githubusercontent.com/grupojk-cambios/grupojk-conversor/main/public/logos/imagen-cierre.jpg',
    texto: '¡Buenas tardes! Hasta mañana'
  };
}

// AVISO DE FALLAS DE LA APERTURA.
//
// Hace falta porque los nodos que mandan a los grupos ahora tienen "seguir aunque falle":
// si un grupo falla, los demas y el estado igual salen, pero la ejecucion queda marcada como
// exitosa y nadie se entera. Este nodo es el que avisa.
//
// Si todo salio bien devuelve [] y no se manda ningun mensaje.

var CHAT_AVISO = '627887509';   // Kelvin

// El texto va a Telegram, que interpreta * _ ` [ ] como formato. Si un mensaje de error trae
// uno suelto, Telegram responde 400 y el aviso NO llega. Por eso se quitan.
function textoError(e){
  var s;
  if (e === null || e === undefined) s = 'sin detalle';
  else if (typeof e === 'string') s = e;
  else if (e.message) s = String(e.message);
  else { try { s = JSON.stringify(e); } catch(x){ s = 'sin detalle'; } }
  return s.replace(/[*_`\[\]]/g, '').slice(0, 200);
}

// null = ese nodo ni llego a correr. [] = corrio y no devolvio nada.
function itemsDe(nodo){
  try { return $(nodo).all(); } catch(e){ return null; }
}

var fallas = [];

// --- Los grupos. Cada item de salida es el grupo que entro en la misma posicion. ---
var envios = itemsDe('Enviar Sticker (Grupos)');
if (envios === null){
  fallas.push('No se mando nada a los grupos.');
} else {
  var grupos = itemsDe('Separar Grupos (Apertura)') || [];
  for (var i = 0; i < envios.length; i++){
    var j = (envios[i] && envios[i].json) || {};
    if (j.error === undefined) continue;
    var g = (grupos[i] && grupos[i].json && grupos[i].json.grupos) || ('grupo ' + (i + 1));
    fallas.push('Grupo ' + g + ' -> ' + textoError(j.error));
  }
}

// --- El estado de WhatsApp. ---
var estado = itemsDe('Estado Texto (Apertura)');
if (estado === null){
  fallas.push('El estado de WhatsApp ni se intento.');
} else {
  for (var k = 0; k < estado.length; k++){
    var e2 = (estado[k] && estado[k].json) || {};
    if (e2.error !== undefined){ fallas.push('Estado de WhatsApp -> ' + textoError(e2.error)); break; }
  }
}

if (!fallas.length) return [];

var cuando = $now.toFormat('dd/LL HH:mm');
var texto = 'OJO: la APERTURA no salio completa (' + cuando + ')\n\n'
  + fallas.map(function(f){ return '- ' + f; }).join('\n')
  + '\n\nSi dice "Connection Closed", a Evolution se le cayo un momento la conexion de WhatsApp.'
  + '\nEntra a Evolution y revisa que la instancia BOT JK Kelvin diga Connected.';

return [{ json: { chatId: CHAT_AVISO, texto: texto } }];

